    "explanation": "Mỗi loại thiết bị điện, dù có vẻ tương tự nhau về chức năng chung, thường có những đặc điểm kĩ thuật cụ thể riêng biệt tuỳ theo thiết kế, cấu tạo của từng nhà sản xuất, từng dòng sản phẩm cụ thể, ví dụ như loại dầu, mỡ bôi trơn phù hợp nhất cho các bộ phận chuyển động cơ khí bên trong, tần suất bảo dưỡng định kì được khuyến nghị cụ thể, hay những bộ phận đặc biệt cần được lưu ý, thận trọng khi thao tác bảo dưỡng; hướng dẫn sử dụng, bảo dưỡng do chính nhà sản xuất cung cấp kèm theo mỗi thiết bị được thiết kế, biên soạn riêng biệt, phù hợp chính xác với những đặc điểm kĩ thuật cụ thể của thiết bị đó, dựa trên hiểu biết chuyên sâu của nhà sản xuất về chính sản phẩm của mình; trong khi đó, việc áp dụng một cách máy móc kinh nghiệm bảo dưỡng chung chung (có thể học được từ việc bảo dưỡng một loại thiết bị khác) cho mọi loại thiết bị khác nhau có nguy cơ không phù hợp, thậm chí trong một số trường hợp có thể gây hại ngược lại cho thiết bị cụ thể đó (ví dụ sử dụng sai loại dầu bôi trơn có thể làm hỏng các bộ phận nhựa, cao su bên trong); chính vì vậy, việc đọc kĩ, tuân thủ đúng theo hướng dẫn sử dụng, bảo dưỡng cụ thể của nhà sản xuất cho từng loại thiết bị luôn được khuyến khích hơn so với chỉ dựa vào kinh nghiệm chung chung, thiếu tính đặc thù."
